import sys,os,re
D=sys.argv[1] if len(sys.argv)>1 else '.'
IMG='data:image/jpeg;base64,'
for fn in ('index.html','en.html'):
    p=os.path.join(D,fn); s=open(p,encoding='utf-8').read()
    if 'b in tail' in s: continue
    a=s.find('<figure class="note-shot">')
    if a<0: continue
    e=s.index('</figure>',a)
    f=s[a:e]
    f=f.replace('<div class="av">F</div>','<div class="av"></div>')
    # mark the last incoming bubble of each run
    f=re.sub(r'<div class="b in">((?:(?!<div class="b).)*?</div>)(?=<div class="b out"|</div>)',r'<div class="b in tail">\1',f)
    s=s[:a]+f+s[e:]
    open(p,'w',encoding='utf-8').write(s)
p=os.path.join(D,'style.css'); c=open(p,encoding='utf-8').read()
if '/*v19*/' not in c:
    c+='/*v19*/.note-shot .av{background:url('+IMG+') center/cover;font-size:0;width:34px;height:34px}\n.note-shot .who{font-size:9.5px;font-weight:600}\n.note-shot .b.in{margin-left:24px;position:relative}\n.note-shot .b.in.tail:before{content:"";position:absolute;left:-24px;bottom:0;width:19px;height:19px;border-radius:50%;background:url('+IMG+') center/cover}\n'
    open(p,'w',encoding='utf-8').write(c)
print('v19 patched')
